function stressAdd(n){const b=currentBoard(),r=rng(Date.now()+n),counts=new Map(b.columns.map(c=>[c.id,b.tasks.filter(t=>t.status===c.id).length]));const start=performance.now();for(let i=0;i<n;i++){const c=b.columns[Math.floor(r()*b.columns.length)],order=counts.get(c.id);counts.set(c.id,order+1);const tags=[];const tagCount=b.tags.length&&r()>.4?1+Math.floor(r()*Math.min(3,b.tags.length)):0;while(tags.length<tagCount){const x=b.tags[Math.floor(r()*b.tags.length)];if(!tags.includes(x))tags.push(x)}b.tasks.push({id:uid('stress'),title:`${titleStarts[Math.floor(r()*titleStarts.length)]} ${titleEnds[Math.floor(r()*titleEnds.length)]}`,description:descriptions[Math.floor(r()*descriptions.length)],status:c.id,assignee:r()<.15?'':people[Math.floor(r()*people.length)].id,priority:priorities[Math.floor(r()*priorities.length)],tags,subtasks:[],comments:[],order,updated:nowIso()})}persist();render();showToast(`${n.toLocaleString('es-CL')} tareas mock añadidas · ${Math.round(performance.now()-start)} ms`)}
function selfTest(){const b=currentBoard(),errors=[];if(b.columns.length<1||b.columns.length>MAX_COLUMNS)errors.push('columnas fuera de límite');if(b.tags.length>MAX_TAGS)errors.push('más de 8 tags');const ids=new Set(b.columns.map(c=>c.id));const taskIds=new Set();for(const t of b.tasks){if(taskIds.has(t.id))errors.push('ID de tarea duplicado');taskIds.add(t.id);if(!ids.has(t.status))errors.push('estado inválido');if(!t.title.trim())errors.push('tarea sin título');if(t.tags.some(x=>!b.tags.includes(x)))errors.push('tag huérfano');if(t.subtasks.length>MAX_SUBTASKS)errors.push('demasiadas subtareas');if(t.comments.length>MAX_COMMENTS)errors.push('demasiados comentarios')}const out=$('#self-test-output');out.hidden=false;out.textContent=errors.length?`FAIL\n${[...new Set(errors)].join('\n')}`:`PASS\n${b.tasks.length} tareas\n${b.columns.length}/5 columnas\n${b.tags.length}/8 tags\nModelo Jira Light íntegro`;showToast(errors.length?'Autoprueba con errores':'Autoprueba superada')}
function clearBoard(){const b=currentBoard();if(!confirm(`¿Vaciar las ${b.tasks.length} tareas de “${b.title}”?`))return;commit('Vaciar tablero',()=>{b.tasks=[]},'Tablero vacío');closeDialog('settings-dialog')}
function resetAll(){if(!confirm('¿Restablecer todos los datos mock?'))return;state=makeSeed();undo=null;renderLimits.clear();persist();render();closeDialog('settings-dialog');showToast('Mocks restablecidos')}
function deleteTask(){const t=taskById(activeTaskId);if(!t||!confirm(`¿Eliminar “${t.title}”?`))return;commit('Eliminar tarea',()=>{currentBoard().tasks=currentBoard().tasks.filter(x=>x.id!==t.id)},'Tarea eliminada');closeDialog('task-dialog');activeTaskId=null}
function duplicateTask(){const t=taskById(activeTaskId);if(!t)return;const copy={...clone(t),id:uid('task'),title:`${t.title} copia`.slice(0,180),order:currentBoard().tasks.filter(x=>x.status===t.status).length,subtasks:t.subtasks.map(s=>({...s,id:uid('st')})),comments:t.comments.map(c=>({...c,id:uid('cm')})),updated:nowIso()};commit('Duplicar tarea',()=>currentBoard().tasks.push(copy),'Tarea duplicada')}
function moveTask(id,status){const t=taskById(id);if(!t||t.status===status)return;commit('Mover tarea',()=>{t.status=status;t.order=currentBoard().tasks.filter(x=>x.status===status).length;t.updated=nowIso()},'Tarea movida')}
